all_data = part16_data + part17_scans
assert len(all_data) == 425, f"Expected 425, got {len(all_data)}"
for i, r in enumerate(all_data, 1):
    assert r['nr_skanu'] == i, f"Mismatch at {i}"
    t = r['transkrypcja'].strip()
    if i >= 326:
        assert '...' not in t[10:-10], f"Mid-ellipsis in scan {i}"

with open('/home/ubuntu/workspace/Gen/main_data_j17_part17.json', 'w', encoding='utf-8') as f:
    json.dump(all_data, f, ensure_ascii=False, indent=2)

print(f"SUCCESS: main_data_j17_part17.json saved with {len(all_data)} records (0 mid-ellipsis).")
